using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Peletnapechkai.Api.Domain.Knowledge;
namespace Peletnapechkai.Api.Infrastructure.Persistence.Configurations;
internal sealed class KnowledgeCandidateConfiguration:IEntityTypeConfiguration<KnowledgeCandidate>{public void Configure(EntityTypeBuilder<KnowledgeCandidate>b){b.ToTable("knowledge_candidates");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.LocaleId).HasColumnName("locale_id");b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(240);b.Property(x=>x.Claim).HasColumnName("claim").HasMaxLength(4000);b.Property(x=>x.SourceUrl).HasColumnName("source_url").HasMaxLength(2048);b.Property(x=>x.AiAssisted).HasColumnName("ai_assisted");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(32);b.Property(x=>x.ReviewedByUserId).HasColumnName("reviewed_by_user_id");b.Property(x=>x.CreatedAt).HasColumnName("created_at");b.Property(x=>x.UpdatedAt).HasColumnName("updated_at");b.HasOne(x=>x.Locale).WithMany().HasForeignKey(x=>x.LocaleId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.LocaleId,x.Status,x.UpdatedAt}).HasDatabaseName("ix_knowledge_locale_status_updated");}}
